-- Q 2026-10-17 (thread "Tank Dossier"): Tank heals harder to trigger. On hit heal cards 13 -> 7;
-- new conditions enteredAt (drawn into slot N), hitBy / blockedType (P/K/S). Needs the engine from the same PR.
update public.cards set effect = 'On hit, if this card was drawn into slot 1 and the facing card is a Kick: Gain 2 HP, gain 3% of your Max HP as HP', effect_json = '[{"hook": "onHit", "if": [{"c": "enteredAt", "n": 1}, {"c": "facingIs", "type": "K"}], "do": [{"a": "heal", "who": "self", "n": 2}, {"a": "heal", "who": "self", "n": 3, "per": "maxHpPct"}]}]'::jsonb where id = 'TK-001';
update public.cards set effect = 'On hit, if this card was drawn into slot 2 and you''ve been hit by a Punch this turn: Gain 2 HP, gain 4% of your Max HP as HP', effect_json = '[{"hook": "onHit", "if": [{"c": "enteredAt", "n": 2}, {"c": "hitBy", "n": 1, "type": "P"}], "do": [{"a": "heal", "who": "self", "n": 2}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]'::jsonb where id = 'TK-002';
update public.cards set effect = 'On hit, if this card was drawn into slot 3 and you''ve been hit by a Kick this turn: Gain 2 HP, gain 6% of your Max HP as HP', effect_json = '[{"hook": "onHit", "if": [{"c": "enteredAt", "n": 3}, {"c": "hitBy", "n": 1, "type": "K"}], "do": [{"a": "heal", "who": "self", "n": 2}, {"a": "heal", "who": "self", "n": 6, "per": "maxHpPct"}]}]'::jsonb where id = 'TK-003';
update public.cards set effect = 'Before action, if you play Charge: All opponent''s Kick cards lose 50% dmg / After action, if you Blocked a Kick this turn: Gain 4 HP', effect_json = '[{"hook": "modify", "if": [{"c": "selfAction", "a": "charge"}], "do": [{"a": "mulDmg", "pct": 50, "target": "enemyAll", "onlyType": "K"}]}, {"hook": "onResolve", "if": [{"c": "blockedType", "n": 1, "type": "K"}], "do": [{"a": "heal", "who": "self", "n": 4}]}]'::jsonb where id = 'TK-005';
update public.cards set effect = 'Before action, if you play Strike and you have Shield: This card +10 dmg / After action, if you Blocked a Punch this turn: Gain 5 HP', effect_json = '[{"hook": "modify", "if": [{"c": "selfAction", "a": "strike"}, {"c": "hasStatus", "who": "self", "kind": "shield"}], "do": [{"a": "addDmg", "n": 10, "target": "this"}]}, {"hook": "onResolve", "if": [{"c": "blockedType", "n": 1, "type": "P"}], "do": [{"a": "heal", "who": "self", "n": 5}]}]'::jsonb where id = 'TK-006';
update public.cards set effect = 'After action, if you play Strike: Gain Shield 10 (absorbs hit dmg, lasts through next turn) / After action, if you Blocked 2+ hits this turn: Gain 4 HP', effect_json = '[{"hook": "onResolve", "if": [{"c": "selfAction", "a": "strike"}], "do": [{"a": "status", "who": "self", "kind": "shield", "n": 10, "turns": 1}]}, {"hook": "onResolve", "if": [{"c": "blockedType", "n": 2}], "do": [{"a": "heal", "who": "self", "n": 4}]}]'::jsonb where id = 'TK-008';
update public.cards set effect = 'On hit, if you''ve been hit by 2+ Kicks this turn: Gain 2 HP, gain 3% of your Max HP as HP', effect_json = '[{"hook": "onHit", "if": [{"c": "hitBy", "n": 2, "type": "K"}], "do": [{"a": "heal", "who": "self", "n": 2}, {"a": "heal", "who": "self", "n": 3, "per": "maxHpPct"}]}]'::jsonb where id = 'TK-011';
update public.cards set effect = 'Before action: All following cards (Kick only) +6 dmg / On hit, if this card hits clean: Gain 2 HP per Kick in your chain', effect_json = '[{"hook": "modify", "do": [{"a": "addDmg", "n": 6, "target": "following", "onlyType": "K"}]}, {"hook": "onHit", "if": [{"c": "hitResult", "r": "clean"}], "do": [{"a": "heal", "who": "self", "n": 2, "per": "chainK"}]}]'::jsonb where id = 'TK-013';
update public.cards set effect = 'After action, if you''ve been hit by a Skill this turn: Max HP −5, gain 2 HP, gain 3% of your Max HP as HP', effect_json = '[{"hook": "onResolve", "if": [{"c": "hitBy", "n": 1, "type": "S"}], "do": [{"a": "maxHp", "who": "self", "n": -5}, {"a": "heal", "who": "self", "n": 2}, {"a": "heal", "who": "self", "n": 3, "per": "maxHpPct"}]}]'::jsonb where id = 'TK-015';
update public.cards set effect = 'After action, if you play Strike and this card hits clean: Opponent can''t Charge next turn', effect_json = '[{"hook": "onResolve", "if": [{"c": "selfAction", "a": "strike"}, {"c": "hitResult", "r": "clean"}], "do": [{"a": "status", "who": "enemy", "kind": "noCharge", "turns": 1}]}]'::jsonb where id = 'TK-020';
update public.cards set effect = 'On hit, if you''ve been hit by a Punch this turn: Gain 4 HP per Punch in your chain', effect_json = '[{"hook": "onHit", "if": [{"c": "hitBy", "n": 1, "type": "P"}], "do": [{"a": "heal", "who": "self", "n": 4, "per": "chainP"}]}]'::jsonb where id = 'TK-022';
update public.cards set effect = 'Before action, if you play Strike and facing card is a Kick: This card dmg x3', effect_json = '[{"hook": "modify", "if": [{"c": "selfAction", "a": "strike"}, {"c": "facingIs", "type": "K"}], "do": [{"a": "mulDmg", "pct": 300, "target": "this"}]}]'::jsonb where id = 'TK-023';
